const steps=()=>`<div class="process"><article><span class="step-number">01 / ЗАМЫСЕЛ</span><h3>Начинаем с пространства</h3><p>Планировка, фотографии, эскиз или просто идея. Важно понять задачу и ожидаемый результат.</p></article><article><span class="step-number">02 / ДЕТАЛИ</span><h3>Собираем решение</h3><p>Геометрия, стекло, крепления и отделка складываются в единый проект.</p></article><article><span class="step-number">03 / ИЗГОТОВЛЕНИЕ</span><h3>Переносим идею в материал</h3><p>Изготовление начинается после согласования размеров, комплектации и чертежей.</p></article><article><span class="step-number">04 / ВОПЛОЩЕНИЕ</span><h3>Доводим до вашего формата</h3><p>Конструкция с доставкой и монтажом или готовые детали для самостоятельной комплектации.</p></article></div>`;
