function approachPage(){return `${crumb([['Как мы работаем']])}<section class="page-intro"><div class="eyebrow">VIP GLASS / ПОДХОД</div><h1>За красивой формой —<br><em>точные решения.</em></h1><p>Размер, материал, крепление и соседние поверхности связаны друг с другом. Поэтому каждый заказ начинается с понимания пространства.</p></section><section class="section" style="padding-top:25px">${steps()}<div class="context-panel"><h3>Два формата работы</h3><p>Первый — изделие с доставкой и монтажом. Второй — изготовление деталей по размерам или чертежам для тех, кто самостоятельно комплектует и устанавливает конструкцию. Выбрать формат можно в карточке решения.</p></div></section><section class="section" style="padding-top:0"><div class="section-top"><h2>Что помогает<br><em>начать предметно.</em></h2></div><div class="service-list"><article><h3>Фотографии пространства</h3><p>Общий вид, проёмы, места примыкания и детали, которые важно учесть.</p></article><article><h3>План и размеры</h3><p>Эскиз, дизайн-проект или рабочий чертёж с известными размерами.</p></article><article><h3>Представление о результате</h3><p>Референс, выбранное решение, нужная прозрачность и характер отделки.</p></article></div></section>${cta()}`}
function projectPage(){return `${crumb([['Мой проект']])}<section class="page-intro"><div class="eyebrow">ВАША ПОДБОРКА / ${project.items.length} ПОЗИЦИЙ</div><h1>Соберём <em>вашу идею.</em></h1><p>Выбранные решения, размеры и чертежи в одном месте. Проект можно дополнить, сохранить и подготовить к обсуждению.</p></section><section class="section" style="padding-top:10px"><div class="brief-page"><div><div id="project-items">${project.items.length?project.items.map(projectItem).join(''):`<div class="project-empty"><h3>Начните с решения<br>или собственного задания.</h3><p>Добавьте изделия из каталога — либо сразу опишите, что вам нужно. Выбор готового типа конструкции необязателен.</p><div class="button-row">${btn('Открыть каталог','#/catalog')}${btn('Изготовить по ТЗ','#/production','clear')}</div></div>`}</div><div class="button-row">${btn('Добавить конструкцию','#/catalog','clear')}${btn('Материал','#/materials','clear')}${btn('Обработку','#/production','clear')}</div>${projectHardwarePreferences()}</div><aside class="project-summary"><h3>Задание к проекту</h3><div class="field"><label for="project-description">Что важно учесть</label><textarea id="project-description" data-project-field="description" placeholder="Пространство, задачи, общий замысел и пожелания…">${esc(project.description)}</textarea></div><div class="form-grid"><div class="field"><label for="project-name">Ваше имя</label><input id="project-name" data-project-field="name" autocomplete="name" value="${esc(project.name)}" placeholder="Необязательно"></div><div class="field"><label for="project-contact">Контакт для обсуждения</label><input id="project-contact" data-project-field="contact" value="${esc(project.contact)}" placeholder="Необязательно"></div></div><div class="attachment-box"><label for="project-files">Чертежи и фотографии</label><input type="file" id="project-files" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.heic,.dwg,.dxf,.doc,.docx,.xlsx,.xls,.zip,.step,.stp"><p>До 50 МБ на файл, до 100 МБ всего. Файлы войдут в скачанный архив.</p><ul class="file-list" id="file-list">${fileList()}</ul></div><div class="project-actions"><button class="btn primary" data-action="export-project">Скачать проект и файлы <span>↓</span></button><button class="btn clear" data-action="export-text">Скачать только задание <span>↓</span></button></div><p class="live-save" id="save-state">Текст и подборка сохраняются в этом браузере.</p><p class="form-note">Отправка заявки в компанию в этой версии ещё не подключена. Скачайте подборку, чтобы сохранить её для обсуждения. Вложения сохраняются в скачанном архиве; после обновления страницы их нужно приложить заново.</p></aside></div></section>`}
function projectItem(item,index){const s=sols.get(item.id),resource=resourceByPath.get(item.resourcePath);return `<article class="project-item" data-uid="${esc(item.uid||index)}">${s||resource?`<a class="project-item-photo" href="${esc(item.url||resource?.url||solutionUrl(s))}">${resource?resourcePhoto(resource,{small:true}):photoMarkup(nodesByPath.get(item.catalogPath)||s,{small:true})}</a>`:''}<div class="project-item-head"><h3>${s||resource?`<a href="${esc(item.url||resource?.url||solutionUrl(s))}">${esc(item.title||resource?.title||s.title)} ↗</a>`:esc(item.title||'Изготовление по ТЗ')}</h3><button class="remove-button" data-remove="${index}">Удалить</button></div><div class="item-meta">${item.kind==='material'?'Материал в составе задания':item.kind==='service'?'Услуга обработки':item.mode==='parts'?'Изготовление деталей по ТЗ':'Изделие с монтажом'}${s?' · '+esc(cats.get(s.category).shortTitle):''}</div><div class="form-grid"><div class="field"><label for="pw-${index}">${esc(item.widthLabel||'Ширина')}, мм</label><input id="pw-${index}" type="number" min="1" step="any" data-item="${index}" data-field="width" value="${esc(item.width)}"></div>${['diameter','side'].includes(item.sizeMode)?'':`<div class="field"><label for="ph-${index}">${esc(item.heightLabel||heightLabel(s))}, мм</label><input id="ph-${index}" type="number" min="1" step="any" data-item="${index}" data-field="height" value="${esc(item.height)}"></div>`}<div class="field"><label for="pq-${index}">Количество</label><input id="pq-${index}" type="number" min="1" step="1" data-item="${index}" data-field="quantity" required value="${esc(item.quantity??1)}"></div></div><div class="field"><label for="pn-${index}">Детали исполнения</label><textarea id="pn-${index}" data-item="${index}" data-field="note">${esc(item.note)}</textarea></div></article>`}
function projectHardwarePreferences(){const items=project.hardwarePreferences||[];if(!items.length)return '';return `<section class="project-hardware"><h2>Пожелания к фурнитуре</h2><p>Эти элементы подбираются в составе конструкций проекта.</p>${items.map((item,i)=>`<article><div><a href="#/hardware/item/${esc(item.id)}"><strong>${esc(item.title)}</strong> ↗</a><p>${esc(item.finishLabel||'Отделка уточняется')}${item.note?' · '+esc(item.note):''}</p></div><button type="button" data-remove-hardware="${i}" aria-label="Удалить пожелание: ${esc(item.title)}">Удалить</button></article>`).join('')}</section>`;}
function fileList(){return files.map((f,i)=>`<li><span>${esc(f.name)} · ${(f.size/1024/1024).toFixed(1)} МБ</span><button data-remove-file="${i}" aria-label="Убрать ${esc(f.name)}">×</button></li>`).join('')}
function structurePage(){const resourceTree=nodes=>`<ul class="visible-tree">${nodes.map(n=>`<li><a href="${n.url}">${esc(n.title)}</a>${n.children.length?resourceTree(n.children):''}</li>`).join('')}</ul>`;return deepUI.structurePage()+`<section class="selection-page expanded-sitemap"><div class="map-grid">${[servicesRoot,materialsRoot].map(root=>`<section class="map-category"><h2><a href="${root.url}">${esc(root.title)} ↗</a></h2>${resourceTree(root.children)}</section>`).join('')}<section class="map-category"><h2><a href="#/hardware">Фурнитура ↗</a></h2><ul class="visible-tree">${hardwareApplications.map(a=>`<li><a href="#/hardware/${a.id}">${esc(a.title)}</a></li>`).join('')}</ul></section></div></section>`;}
function notFound(){return `<section class="section"><div class="eyebrow">СТРАНИЦА НЕ НАЙДЕНА</div><h1 style="margin:25px 0">Вернёмся <em>к выбору.</em></h1><p>Этот адрес не соответствует странице каталога.</p><div class="button-row">${btn('Открыть каталог','#/catalog')}</div></section>`}
function legacyGroupNode(c,g){
 const root=rootById.get(c.id);
 const exact=catalogNodes.find(n=>n.category===c.id&&!n.isLeaf&&n.id===g.id);
 if(exact)return exact;
 const source=solutions.find(s=>s.category===c.id&&inGroup(s,g.id));
 const leaf=source&&firstLeafBySolution.get(source.id);
 return leaf?nodesByPath.get(leaf.ancestors[1]||leaf.ancestors[0]):root;
}
function parseRoute(){const raw=location.hash?.startsWith('#/')?location.hash.slice(1):(location.pathname||'/')+(location.search||'');const [rawPath,query='']=raw.split('?'),normalized=rawPath.replace(/\/+$/,'')||'/',path=retiredHardwareRoutes[normalized]||normalized;if(path!==normalized&&window.history?.replaceState)window.history.replaceState({},'',path);return {path,parts:path.split('/').filter(Boolean),params:new URLSearchParams(path===normalized?query:'')}}
function canonicalRoutePath(r){const node=nodesByPath.get(r.path)||resourceByPath.get(r.path);if(node)return node.path;const [first,second,third]=r.parts;if(first==='solution')return firstLeafBySolution.get(second)?.path||r.path;if(first==='catalog'&&r.parts.length===3){const category=cats.get(second),group=category?.groups.find(x=>x.id===third);if(group)return legacyGroupNode(category,group).path;}if(first==='production'&&second==='materials')return '/materials'+(r.parts.length>2?'/'+r.parts.slice(2).join('/'):'');return r.path;}
function routeMetadata(r,title,html){
 const path=canonicalRoutePath(r),node=nodesByPath.get(path)||resourceByPath.get(path),h=hardware.find(x=>x.path===path),app=hardwareApplications.find(x=>path==='/hardware/'+x.id),hwType=hardwareTypeByPath.get(path);
 let trail=[{path:'/',title:'Главная'}],intro='';
 if(node){if(node.category)trail.push({path:'/catalog',title:'Каталог'});trail.push(...node.ancestors.map(p=>nodesByPath.get(p)||resourceByPath.get(p)),node);intro=node.intro||'';title=node.title;}
 else if(hwType){trail.push({path:'/hardware',title:'Фурнитура конструкций'},{path:'/hardware/'+hwType.category,title:hwType.applicationTitle},hwType);intro=hwType.intro;title=hwType.title;}
 else if(h||app){trail.push({path:'/hardware',title:'Фурнитура конструкций'},h||{...app,path});intro=(h||app).intro;title=(h||app).title;}
 else if(path!=='/'){if(path.startsWith('/portfolio/'))trail.push({path:'/portfolio',title:'Портфолио'});else if(path.startsWith('/journal/'))trail.push({path:'/journal',title:'Журнал'});else if(path.startsWith('/stories/'))trail.push({path:'/stories',title:'Истории'});else if(path.startsWith('/reels/'))trail.push({path:'/reels',title:'Рилс'});if(path==='/production/request')trail.push({path:'/production',title:'Производство'});trail.push({path,title});}
 else intro='Стекло и зеркала на заказ. Интерьерные решения с установкой и изготовление деталей по размерам и чертежам.';
 const labels=trail.slice(1).map(n=>n.title),parents=labels.slice(0,-1).filter(x=>x!=='Каталог');
 const pageTitle='VIP Glass — '+title+(parents.length?' · '+parents.reverse().join(' / '):'');
 intro=intro||String(html.match(/<p\b[^>]*>([\s\S]*?)<\/p>/i)?.[1]||title).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
 const description=title+'. '+intro+(labels.length>1?' Раздел: '+labels.slice(0,-1).join(' / ')+'.':'');
 document.title=pageTitle;const desc=$('meta[name=description]');if(desc)desc.content=description;
 const origin='https://vipglass.example',canonical=$('link[rel=canonical]');if(canonical)canonical.href=origin+path;
 const schema=$('script[type="application/ld+json"]');if(schema)schema.textContent=JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':node?.children.length?'CollectionPage':'WebPage',url:origin+path,name:title,description,inLanguage:'ru'},{'@type':'BreadcrumbList',itemListElement:trail.map((x,i)=>({'@type':'ListItem',position:i+1,name:x.title,item:origin+x.path}))}]});
}
function cleanInternalLinks(){for(const a of $$('a[href^="#/"]'))a.setAttribute('href',a.getAttribute('href').slice(1));}
