function populateHardwareFinishes(id){const item=hardwareById.get(id),select=$('#hardware-finish');if(!select)return;select.disabled=!item;select.innerHTML=item?'<option value="">Уточнить при подборе</option>'+item.finishes.map(f=>`<option value="${f.id}">${esc(f.label)}</option>`).join(''):'<option value="">Сначала выберите вид</option>';}
