async function exportProject(button,withFiles){if(!project.items.length&&!String(project.description).trim()&&!files.length){toast('Добавьте решение или опишите задачу');return}const inputList=$$('#project-items input');if(inputList.some(i=>!i.reportValidity()))return;button.disabled=true;const label=button.innerHTML;button.textContent='Подготавливаем…';try{const text=makeProjectText({...project,files:files.map(f=>({name:f.name}))},solutions)+'\n\nМатериал прозрачных стеклянных элементов: осветлённое Crystal Vision, без зелёного оттенка.\n';if(withFiles){const entries=[{name:'Задание VIP Glass.txt',data:text},{name:'project.json',data:JSON.stringify({...project,files:files.map(f=>({name:f.name,size:f.size})),material:materialText},null,2)}];for(let i=0;i<files.length;i++)entries.push({name:`Приложения/${String(i+1).padStart(2,'0')}-${files[i].name.replace(/[\\/]/g,'_')}`,data:await files[i].arrayBuffer()});download(makeZip(entries),'VIP-Glass-project.zip','application/zip')}else download(text,'VIP-Glass-project.txt','text/plain;charset=utf-8');toast('Проект подготовлен для скачивания')}catch{toast('Не удалось подготовить архив. Попробуйте скачать только задание.')}finally{button.disabled=false;button.innerHTML=label}}
