$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('hashchange',()=>{if(location.hash?.startsWith('#/')&&window.history?.replaceState){window.history.replaceState({},'',location.hash.slice(1));}render();});
window.addEventListener('popstate',()=>render());
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch()}});
if(location.hash?.startsWith('#/')&&window.history?.replaceState)window.history.replaceState({},'',location.hash.slice(1));
render({scroll:false});
